/// How `nf.commands.register` describes a command: everything optional. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct CommandDefinition {
    /// One line for the server's help.
    pub description: Option<String>,
    /// A permission node the sender needs. On Paper the command (or subcommand) doesn't exist for a player without it: not in tab completion, not when typed. The console has every permission.
    pub permission: Option<String>,
    /// Other names for it.
    pub aliases: Option<Vec<String>>,
    /// What comes after it, in order. Arguments with a `default` are optional and must come last; a `text` argument takes the rest of the line, so it must be the last one.
    pub arguments: Option<Vec<shapes::CommandArgument>>,
    /// Words that can come next, each with its own arguments, permission and handler: `{ add = { ... }, remove = { ... } }`. Names are lowercase letters, digits, `_` and `-`. A subcommand wins over an argument when both could take the word.
    pub subcommands: Option<BTreeMap<String, shapes::Subcommand>>,
    /// Refuses the console (and command blocks) with a message, so the handler can count on `event.player`. A subcommand under a `players_only` command is players-only too.
    pub players_only: Option<bool>,
}

/// A word after a command (or after another subcommand) with its own arguments and handler: `/shop give <player>`. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct Subcommand {
    /// One line for the server's help.
    pub description: Option<String>,
    /// A permission node the sender needs. On Paper the command (or subcommand) doesn't exist for a player without it: not in tab completion, not when typed. The console has every permission.
    pub permission: Option<String>,
    /// What comes after it, in order. Arguments with a `default` are optional and must come last; a `text` argument takes the rest of the line, so it must be the last one.
    pub arguments: Option<Vec<shapes::CommandArgument>>,
    /// Words that can come next, each with its own arguments, permission and handler: `{ add = { ... }, remove = { ... } }`. Names are lowercase letters, digits, `_` and `-`. A subcommand wins over an argument when both could take the word.
    pub subcommands: Option<BTreeMap<String, shapes::Subcommand>>,
    /// Refuses the console (and command blocks) with a message, so the handler can count on `event.player`. A subcommand under a `players_only` command is players-only too.
    pub players_only: Option<bool>,
    /// Runs when someone types it. A handler that errors is logged and whoever typed the command is told; the command stays.
    pub handler: Option<Function>,
}

/// One argument of a command. Its `type` decides what may be typed, what tab completion offers, the usage message, and the value the handler gets in `event.arguments[name]`. On Paper it's a real Brigadier argument, so the player's client checks and completes it as they type. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct CommandArgument {
    /// Its key in `event.arguments`, and what the usage message shows (`<amount>`). Letters, digits and `_`, not starting with a digit; unique within the command.
    pub name: String,
    /// What it takes, and what the handler gets: `"word"`: one word, a `string`. `"text"`: the rest of the line, spaces and all, a `string`. `"integer"`: a whole number, within `min` and `max` when given, a `integer`. `"number"`: any number, within `min` and `max` when given, a `number`. `"boolean"`: `true` or `false`, a `boolean`. `"choice"`: one of `choices`, as typed, a `string`. `"player"`: an online player by name, or a selector that picks exactly one (`@p`, `@s`), a `Player`. `"players"`: a name or a selector (`@a`, `@a[distance=..10]`) picking at least one player, a `Player[]`. `"entity"`: a selector that picks exactly one entity, an online player's name, or a loaded entity's UUID (a `Player` for a player), an `Entity`. `"entities"`: a selector, name or UUID picking at least one entity, an `Entity[]`. `"world"`: a loaded world by name, a `World`. `"position"`: three coordinates, each a number, `~` (relative to the sender) or `^` (local to where they look); whole numbers are block centres in x and z, as in vanilla commands, a `Vec3`. `"location"`: the same three coordinates, in the sender's world facing the way they face (the default world and no facing from the console), a `Location`. `"block_state"`: a block state like `oak_stairs[facing=east]`, given back in full with every property (`"minecraft:oak_stairs[facing=east,half=bottom,…]"`), a `string`. `"item"`: an item like `diamond_sword`, or with components on Paper (`diamond_sword[enchantments={sharpness:3}]`), an `Item`. `"centity"`: a live centity by its instance id (completed from the live ones), a `Centity`. `"centity_kind"`: one of the project's centities, by its folder name, a `string`. `"menu"`: one of the project's menus, by its id, a `string`. `"dialog"`: one of the project's dialogs, by its id, a `Dialog`.
    pub r#type: String,
    /// Makes it optional: the value the handler gets when it's left out. A value of the argument's type (a number for `integer`, a `Vec3` for `position`, one of `choices` for `choice`), or `false` for "nothing", the way to make a `player` or `item` argument optional: then `event.arguments.target or event.player`.
    pub default: Value,
    /// The smallest value an `integer` or `number` argument takes.
    pub min: Option<f64>,
    /// The largest value an `integer` or `number` argument takes.
    pub max: Option<f64>,
    /// What a `choice` argument takes: single words. Required for `choice`, and only for it.
    pub choices: Option<Vec<String>>,
    /// Tab completion of its own, instead of what its type offers. Gets the event so far (`event.arguments` holds the arguments before this one) and what has been typed of this argument; returns the suggestions. NetherForge keeps those starting with `partial`. Runs in the module's scope, within its instruction budget, every time a player's client asks, so keep it cheap.
    pub complete: Option<Function>,
}

