/// What `nf.teams.create` makes a team with. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TeamOptions {
    /// What it's called where Minecraft names a team, MiniMessage. Default its name.
    pub display_name: Option<values::Text>,
    /// What goes before each member's name, MiniMessage. Default none.
    pub prefix: Option<values::Text>,
    /// What goes after each member's name, MiniMessage. Default none.
    pub suffix: Option<values::Text>,
    /// The colour of members' names and glow. Default none.
    pub color: Option<String>,
    /// Whether members can hurt each other. Default `true`.
    pub friendly_fire: Option<bool>,
    /// Whether members see each other while invisible. Default `true`.
    pub see_invisible_teammates: Option<bool>,
    /// `"always"` (the default), `"never"`, `"hide_for_other_teams"` (only teammates see them) or `"hide_for_own_team"` (only players outside the team see them).
    pub nametags: Option<String>,
    /// `"always"` (the default), `"never"`, `"push_other_teams"` (members pass through each other) or `"push_own_team"` (members push only each other).
    pub collision: Option<String>,
}

/// What a schedule is called and what to do about a run the server missed. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct ScheduleOptions {
    /// A name for the schedule, which what it last ran is kept under, so it's known across restarts. Lowercase letters, digits and `_` (starting with a letter or digit, at most 64 characters), and no two of a package's live schedules share one. Default none: the schedule is forgotten when it stops.
    pub id: Option<String>,
    /// Run once when the script starts if a run was missed since the schedule last ran (the server was off over its time). Needs an `id`; a schedule seen for the first time has missed nothing. Default `false`: a missed run is skipped.
    pub catch_up: Option<bool>,
}

/// One statement of `db:transaction`.
#[derive(Clone, Debug)]
pub struct DatabaseStatement {
    /// One SQL statement in the database's own dialect (SQLite's for the package's own database; MySQL's or PostgreSQL's for a connection the server owner set up), with `?` where a value goes: the values come in `params`, never inside the text, so a name a player typed can't become SQL. A second statement after a `;` is an error: use `db:transaction` for several. On PostgreSQL a literal `?` (the JSON operators) is written `??`.
    pub sql: String,
    /// The values for the `?`s, in order: `{ player_name, 5 }`. Each is a `string`, `number`, `integer` or `boolean` (stored as 1 or 0); a hole in the list (`{ 1, nil, 3 }`) is SQL `NULL`, and so are the last `?`s when the list is shorter (Lua can't tell `{ name, nil }` from `{ name }`). Any other kind of value is an error, and more values than `?`s fails the statement.
    pub params: Value,
}

/// What `db:execute` (and each statement of `db:transaction`) did.
#[derive(Clone, Debug)]
pub struct DatabaseResult {
    /// How many rows it inserted, updated or deleted.
    pub changes: i64,
    /// On the package's own database, the `rowid` of the last row it inserted (the new row's `INTEGER PRIMARY KEY`), or `nil` when nothing was ever inserted. On a MySQL connection, the `AUTO_INCREMENT` key the statement generated, or `nil` when it generated none. On PostgreSQL always `nil`: ask for the key with `INSERT ... RETURNING id` through `db:query`.
    pub last_insert_id: Option<i64>,
}

/// What `nf.http.request` takes.
#[derive(Clone, Debug)]
pub struct HttpRequestOptions {
    /// An `http://` or `https://` URL, without a user name or password in it (send credentials in a header). Its host must be one the calling package declares in `requires`.
    pub url: String,
    /// The HTTP method; `"GET"` when left out.
    pub method: Option<String>,
    /// Request headers by name. `Host`, `Content-Length`, `Transfer-Encoding`, `Connection`, `Upgrade` and the like are set by the server and refused here. A `User-Agent` of `NetherForge` is sent unless you give one. `Authorization`, `Cookie` and `Proxy-Authorization` are dropped when a redirect leads to another host.
    pub headers: Option<BTreeMap<String, String>>,
    /// The request body, as text (UTF-8). Its size is limited by `http.max-request-bytes` in the server's `config.yml`. A `GET`, `HEAD` or `OPTIONS` can't have one.
    pub body: Option<String>,
}

/// What `nf.http.request` gives.
#[derive(Clone, Debug)]
pub struct HttpResponse {
    /// The status code: `200`, `404`.
    pub status: i64,
    /// The response headers by name in lowercase (`response.headers["content-type"]`); a header sent more than once is its values joined with `, `.
    pub headers: BTreeMap<String, String>,
    /// The body as text, decoded by the charset the response names (UTF-8 when it names none), so a response that isn't text (an image) doesn't survive. Its size is limited by `http.max-response-bytes` in the server's `config.yml`.
    pub body: String,
    /// The URL the response came from: the request's own, or where its redirects ended.
    pub url: String,
}

/// What `nf.http.stream` takes: `nf.http.request`'s options, and `format`.
#[derive(Clone, Debug)]
pub struct HttpStreamOptions {
    /// An `http://` or `https://` URL, as for `nf.http.request`. Its host must be one the calling package declares in `requires`.
    pub url: String,
    /// The HTTP method; `"GET"` when left out.
    pub method: Option<String>,
    /// Request headers by name, as for `nf.http.request`. A `format` of `"events"` sends `Accept: text/event-stream` unless you give an `Accept`.
    pub headers: Option<BTreeMap<String, String>>,
    /// The request body, as for `nf.http.request` (`http.max-request-bytes`).
    pub body: Option<String>,
    /// How the response is split into messages. `"lines"` (the default): one message per line, without its line ending (NDJSON, a log tail). `"events"`: Server-Sent Events (`text/event-stream`), one message per event, with its `type` and `id`; comments and `retry` are skipped. `"chunks"`: the text as it arrives, in pieces of no particular size. A line or event over `connections.max-message-bytes` ends the stream (reason `"limit"`); text is UTF-8.
    pub format: Option<String>,
}

/// What `nf.http.websocket` takes.
#[derive(Clone, Debug)]
pub struct WebSocketOptions {
    /// A `ws://` or `wss://` URL, without a user name or password in it. Its host must be one the calling package declares in `requires.http`.
    pub url: String,
    /// Headers for the opening request (an `Authorization`), with `nf.http.request`'s rules. The `Sec-WebSocket-*` headers are the server's to set.
    pub headers: Option<BTreeMap<String, String>>,
    /// Subprotocols to offer (`Sec-WebSocket-Protocol`), in order of preference; `socket:protocol()` says which one the other side chose.
    pub protocols: Option<Vec<String>>,
}

/// A stream's response began.
#[derive(Clone, Debug)]
pub struct HttpStreamOpenEvent {
    /// The stream.
    pub stream: handles::HttpStream,
    /// The status code: `200`, `404`.
    pub status: i64,
    /// The response headers by name in lowercase, as `nf.http.request` gives them.
    pub headers: BTreeMap<String, String>,
}

/// A piece of a stream arrived.
#[derive(Clone, Debug)]
pub struct HttpStreamMessageEvent {
    /// The stream.
    pub stream: handles::HttpStream,
    /// The line (without its line ending), the event's data (its `data:` lines joined with line breaks), or the chunk.
    pub data: String,
    /// For `format = "events"`: the event's type, `"message"` when it names none. `nil` for the other formats.
    pub r#type: Option<String>,
    /// For `format = "events"`: the last event id the stream set (`id:`), which a script reconnecting sends back as `Last-Event-ID`. `nil` when none was set, and for the other formats.
    pub id: Option<String>,
}

/// A stream ended.
#[derive(Clone, Debug)]
pub struct HttpStreamEndEvent {
    /// The stream.
    pub stream: handles::HttpStream,
    /// Why: the server ended the response; `close()` was called; the connection couldn't be made or broke (a name that doesn't resolve, an address that isn't allowed, a refused connection, a redirect it couldn't follow, no answer within `http.timeout-seconds`); an owner's limit in `config.yml`'s `http:` section was reached (too many connections open, the request rate, a message over `connections.max-message-bytes`, the package's `connections.bytes-per-minute`); nothing arrived for `connections.idle-seconds`; or the script that opened it unloaded.
    pub reason: String,
    /// The response's status, when it had opened.
    pub status: Option<i64>,
    /// What went wrong, in words, for `"failed"` and `"limit"`; `nil` otherwise.
    pub detail: Option<String>,
}

/// A WebSocket opened.
#[derive(Clone, Debug)]
pub struct WebSocketOpenEvent {
    /// The socket.
    pub socket: handles::WebSocket,
    /// The subprotocol the other side chose, or `nil`.
    pub protocol: Option<String>,
    /// The opening response's headers by name in lowercase.
    pub headers: BTreeMap<String, String>,
}

/// A text message arrived on a WebSocket.
#[derive(Clone, Debug)]
pub struct WebSocketMessageEvent {
    /// The socket.
    pub socket: handles::WebSocket,
    /// The message.
    pub data: String,
}

/// A WebSocket ended.
#[derive(Clone, Debug)]
pub struct WebSocketEndEvent {
    /// The socket.
    pub socket: handles::WebSocket,
    /// Why: the other side closed it (`code` and `detail` say how); `close()` was called; the connection couldn't be made, was refused or broke (as for a stream; a server that doesn't speak WebSocket at that URL, or a binary message); an owner's limit in `config.yml`'s `http:` section was reached (too many connections open, the request rate, a message over `connections.max-message-bytes`, the package's `connections.bytes-per-minute`); nothing was sent or arrived for `connections.idle-seconds`; or the script that opened it unloaded.
    pub reason: String,
    /// For `"finished"`: the close code the other side sent (`1000` is a normal close).
    pub code: Option<i64>,
    /// For `"finished"`: the reason the other side gave, if any. For `"failed"` and `"limit"`: what went wrong, in words. `nil` otherwise.
    pub detail: Option<String>,
}

