pub struct ParticlePlayOptions {
    /// Only these players see it (still only those within range). Players who leave drop out. Default: everyone in range.
    pub viewers: Option<Vec<handles::Player>>,
    /// Multiplies its distances: shape sizes, offsets, spreads and speeds (not dust sizes). More than 0, at most 16. Default 1.
    pub scale: Option<f64>,
    /// Whether it starts again after its last tick, until it's stopped. Default: what its file says.
    pub r#loop: Option<bool>,
    /// Follow this from the start, as `effect:follow` does. Each tick, before it spawns anything, the effect moves to the target: its position (a node's `world_position()`), facing the target's yaw (a node's centity's), pitch 0. When the target stops existing (a removed centity, a player who left, an entity that died or was removed, a centity or entity whose chunk unloaded) the effect ends with reason `"target_gone"`. `location_or_position` is still needed: it's where the effect is if the target is already gone, which ends it on its first tick.
    pub follow: Option<handles::Handle>,
    /// With `follow`: where the effect sits from the target, as for `effect:follow`. Without `follow` it's an error.
    pub offset: Option<values::Vec3>,
}

/// A particle effect ended.
#[derive(Clone, Debug)]
pub struct EffectEndEvent {
    /// The effect.
    pub effect: handles::Effect,
    /// Why: it played to its end; `stop()` was called; what it followed went; its file was deleted; or the script that played it unloaded (a reload, its centity removed, the server stopping).
    pub reason: String,
}

/// How `nf.cutscenes.play` plays a cutscene. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct CutscenePlayOptions {
    /// Where the path's coordinates are measured from: every camera position is added to it (the path is moved, not turned). A `Location` also says which world the cutscene is in (its `yaw` and `pitch` are not used); a `Vec3` is in the player's world. Default: the path's coordinates are the world's, in the player's world.
    pub origin: Option<unions::LocationOrVec3>,
    /// Whether the player may end it early by sneaking (reason `"skipped"`). Default: what the cutscene's file says, which defaults to `false`.
    pub skippable: Option<bool>,
}

/// A cutscene ended.
#[derive(Clone, Debug)]
pub struct CutsceneEndEvent {
    /// The cutscene.
    pub cutscene: handles::Cutscene,
    /// Who was watching.
    pub player: handles::Player,
    /// Why: it played to its end; `stop()` was called; the player sneaked, in a skippable one; another cutscene was played for the player; the player left the server; or the script that played it unloaded (a reload, the server stopping).
    pub reason: String,
}

/// A cutscene reached a named cue.
#[derive(Clone, Debug)]
pub struct CutsceneCueEvent {
    /// The cutscene.
    pub cutscene: handles::Cutscene,
    /// Who is watching.
    pub player: handles::Player,
    /// The cue's `event` name in the cutscene's file.
    pub cue: String,
}

/// A screen `nf.screens.create` makes: `width` and `height` are required; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct ScreenOptions {
    /// Maps across, 1 to 16.
    pub width: i64,
    /// Maps down, 1 to 16.
    pub height: i64,
    /// Keeps its maps' numbers for good, across restarts (see `nf.screens.create`): any name, unique among the screens this package's scripts make. Making one with a key a screen that's still there has is an error.
    pub key: Option<String>,
    /// What it starts filled with. A colour, `#rrggbb` (drawn as the nearest of the colours a map can show), or `"clear"` for none: the map shows through. Default `"clear"`.
    pub background: Option<String>,
    /// `"near"` (the default): every player near where it hangs, or everyone online while it hangs nowhere. `"script"`: only those `show_to` shows it to.
    pub viewers: Option<String>,
    /// How near is near, in blocks: 1 to 256 (default 64).
    pub range: Option<i64>,
    /// Whether its frames glow, drawing it at full brightness (default true).
    pub glowing: Option<bool>,
    /// How far a click reaches it from, in blocks: 0 to 64 (default 24). Within the game's reach a click on a frame always counts.
    pub click_range: Option<f64>,
}

/// How a shape is drawn: `fill`, `outline`, or both (neither is an error).
#[derive(Clone, Debug)]
pub struct ShapeStyle {
    /// Its inside. A colour, `#rrggbb` (drawn as the nearest of the colours a map can show), or `"clear"` for none: the map shows through.
    pub fill: Option<String>,
    /// Its edge. A colour, `#rrggbb` (drawn as the nearest of the colours a map can show), or `"clear"` for none: the map shows through.
    pub outline: Option<String>,
    /// The outline's width, in pixels: 1 to 32 (default 1).
    pub thickness: Option<i64>,
    /// A rectangle's rounded corners, in pixels (default 0).
    pub radius: Option<i64>,
}

/// How text is drawn on a screen. Every key is optional.
#[derive(Clone, Debug)]
pub struct ScreenTextOptions {
    /// `"default"` (the game's own map font, the default) or one of the project's (`screen_fonts/<id>/`).
    pub font: Option<String>,
    /// Its colour where the text sets none, `#rrggbb` (default white).
    pub color: Option<String>,
    /// Each pixel of the font drawn this many pixels a side: 1 to 8 (default 1).
    pub scale: Option<i64>,
    /// Where `x` is: its left (the default), its middle or its right, line by line.
    pub align: Option<String>,
    /// Breaks lines at spaces so none is wider than this, in pixels.
    pub width: Option<i64>,
    /// Draws a shadow a pixel down and right of every pixel, in this colour.
    pub shadow: Option<String>,
    /// Pixels from one line's top to the next's (default the font's).
    pub line_height: Option<i64>,
}

/// How big text is drawn, in pixels.
#[derive(Clone, Debug)]
pub struct ScreenTextSize {
    /// Its widest line.
    pub width: i64,
    /// All its lines.
    pub height: i64,
}

/// How a picture is drawn on a screen. Every key is optional.
#[derive(Clone, Debug)]
pub struct ScreenImageOptions {
    /// Drawn this wide, in pixels (default its own width, or kept in shape with `height`).
    pub width: Option<i64>,
    /// Drawn this tall, in pixels (default its own height, or kept in shape with `width`).
    pub height: Option<i64>,
    /// How its colours become map colours: `"floyd_steinberg"` (the default) spreads each pixel's error to its neighbours, best for photos; `"ordered"` uses a fixed pattern; `"none"` takes each pixel's nearest.
    pub dither: Option<String>,
}

/// How `screen:play` plays a video. Every key is optional.
#[derive(Clone, Debug)]
pub struct VideoPlayOptions {
    /// Starts it again when it ends (default false).
    pub r#loop: Option<bool>,
    /// How fast: 0.25 to 4 (default 1). Its sound plays only at 1.
    pub speed: Option<f64>,
    /// Where to start, in seconds (default 0).
    pub start: Option<f64>,
    /// Its sound's volume, 0 to 1 (default 1); 0 plays it silent.
    pub volume: Option<f64>,
    /// Where its left is on the screen, in pixels (default 0).
    pub x: Option<i64>,
    /// Where its top is on the screen, in pixels (default 0).
    pub y: Option<i64>,
    /// How near where the screen hangs a player must be to hear it, in blocks (default 32). A screen that hangs nowhere plays its sound to everyone it's drawn for.
    pub audio_range: Option<f64>,
}

/// A pixel of a screen a player aims at.
#[derive(Clone, Debug)]
pub struct ScreenPoint {
    /// The screen: the player's own view of it, when they have one.
    pub screen: handles::Screen,
    /// From its left edge.
    pub x: i64,
    /// From its top edge.
    pub y: i64,
    /// From the player's eyes, in blocks.
    pub distance: f64,
}

/// A player clicked a screen.
#[derive(Clone, Debug)]
pub struct ScreenClickEvent {
    /// The screen clicked: the player's own view of it, when they have one.
    pub screen: handles::Screen,
    /// Who clicked.
    pub player: handles::Player,
    /// The pixel aimed at, from the left edge.
    pub x: i64,
    /// From the top edge.
    pub y: i64,
    /// Which button.
    pub click: String,
}

/// The pixel a player aims at on a screen moved.
#[derive(Clone, Debug)]
pub struct ScreenHoverEvent {
    /// The screen: the player's own view of it, when they have one.
    pub screen: handles::Screen,
    /// Who.
    pub player: handles::Player,
    /// The pixel aimed at now, from the left edge.
    pub x: i64,
    /// From the top edge.
    pub y: i64,
}

/// A player stopped aiming at a screen.
#[derive(Clone, Debug)]
pub struct ScreenLeaveEvent {
    /// The screen.
    pub screen: handles::Screen,
    /// Who.
    pub player: handles::Player,
}

/// A video stopped playing.
#[derive(Clone, Debug)]
pub struct PlaybackEndEvent {
    /// The playback.
    pub playback: handles::Playback,
    /// Why: it played to its end (and doesn't loop); `stop()` was called; another video was played on the screen; the screen went; or the script that played it unloaded.
    pub reason: String,
}

/// A frame of a video was drawn.
#[derive(Clone, Debug)]
pub struct PlaybackFrameEvent {
    /// The playback.
    pub playback: handles::Playback,
    /// Which frame, 0 first.
    pub frame: i64,
    /// Its time in the video, in seconds.
    pub time: f64,
}

/// How `nf.time.format` and `nf.time.parse` read a clock time. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TimeOptions {
    /// Which time zone the clock time is in: an IANA name like `"Europe/London"` or `"America/New_York"`, `"UTC"`, or an offset like `"+02:00"`. Default the server owner's zone (`schedules.time-zone` in `config.yml`, the server's own by default), the one `nf.schedule` runs in. A zone the server doesn't know is an error.
    pub zone: Option<String>,
}

/// Which noise `nf.random.noise2` and `noise3` give. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct NoiseOptions {
    /// Which noise: each seed is a different pattern. Default 0.
    pub seed: Option<i64>,
    /// What the coordinates are multiplied by first: smaller is smoother and wider (0.05 changes over about 20 blocks). Default 1.
    pub scale: Option<f64>,
}

/// How `nf.encoding.base64_encode` writes base64. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct Base64Options {
    /// Whether to use the URL-safe alphabet (`-` and `_` for `+` and `/`), for a URL or a token. Default `false`.
    pub url_safe: Option<bool>,
    /// Whether to end with `=` to a multiple of four characters. Default `true`.
    pub padding: Option<bool>,
}

/// How `nf.crypto.hash` hashes. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct HashOptions {
    /// The hash. Default `"sha256"`.
    pub algorithm: Option<String>,
    /// How the result is written: `"hex"` (lowercase), or `"base64"`. Default `"hex"`.
    pub encoding: Option<String>,
}

/// How `nf.crypto.sign` signs. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct SigningOptions {
    /// The secret to sign with.
    pub secret: String,
    /// The hash. Default `"sha256"`.
    pub algorithm: Option<String>,
    /// How the result is written: `"hex"` (lowercase), or `"base64"`. Default `"hex"`.
    pub encoding: Option<String>,
}

/// How `nf.text.measure` measures. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TextMeasureOptions {
    /// The text display's scale (its node's, and its parents'). Default 1.
    pub scale: Option<f64>,
}

/// How big text draws on a text display, in blocks: what an `anchor`ed text display is placed by.
#[derive(Clone, Debug)]
pub struct TextSize {
    /// Its widest line: every character and the gap after it.
    pub width: f64,
    /// Its lines, a quarter of a block each at scale 1.
    pub height: f64,
}

/// What `nf.test.network_server` takes, the first time it names a server. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestNetworkServerOptions {
    /// The group it's an instance of, as `network.group` says on a server.
    pub group: Option<String>,
    /// How many players it takes; any number when left out.
    pub capacity: Option<i64>,
    /// Where it is in its life as it joins; `ready` when left out.
    pub state: Option<String>,
    /// Whether it takes players; `true` when left out.
    pub accepting: Option<bool>,
}

/// What `nf.test.network_status` says of another server. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestNetworkStatus {
    /// Where it is in its life; as it was when left out.
    pub state: Option<String>,
    /// Whether it takes players; as it was when left out.
    pub accepting: Option<bool>,
}

/// This server's role in the test's network, for `nf.test.network_role`. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestNetworkRole {
    /// The preset: what it may do unless the rest says more.
    pub role: String,
    /// The namespaces whose channels and maps it has whole.
    pub owns: Option<Vec<String>>,
    /// What's shared with it of others', as `hub.properties` spells it: `"lobby:return(request)"`, `"events:*(read)"`.
    pub shares: Option<Vec<String>>,
    /// Whether it sees other servers' players; the preset's when left out.
    pub presence: Option<bool>,
    /// Where it may send players; the preset's when left out.
    pub send_to: Option<Vec<String>>,
    /// Whether it may ban and mute across the network.
    pub moderation: Option<bool>,
}

/// A report the test's network has, from `nf.test.network_reports`.
#[derive(Clone, Debug)]
pub struct TestNetworkReport {
    /// The reported player's name.
    pub player: String,
    /// Why.
    pub reason: String,
    /// What else it said, if anything.
    pub details: Value,
    /// Who reported them, if a player did.
    pub by: Option<String>,
}

/// A message another server of a test's network heard, from `nf.test.network_received`.
#[derive(Clone, Debug)]
pub struct TestNetworkMessage {
    /// The channel's name, as the calling package names it.
    pub channel: String,
    /// What was published.
    pub value: Value,
    /// The server it was published on.
    pub server: String,
}

/// What `nf.test.stub_wasm` answers a module with. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestWasmStub {
    /// An instance's functions by name: each gets the call's `arguments` and returns its results, a list for `call` (`{ 5 }`) or a string for `call_text`.
    pub functions: Option<BTreeMap<String, Function>>,
    /// What `module:run` gives: it gets the run's options (`stdin`, `arguments`, `environment`) and returns a result table.
    pub run: Option<Function>,
    /// A started program's answer to each line it's sent: the lines it prints (to its standard output), or `nil` for none.
    pub input: Option<Function>,
}

/// Where `nf.test.shown` looks. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestShownOptions {
    /// Whether `slot` is one of the window they have open, numbered from 0 as `menu:slot` numbers them.
    pub menu: Option<bool>,
}

/// How `nf.test.click` clicks. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestClickOptions {
    /// Which hand clicks, and whose item is used. Default `"main_hand"`.
    pub hand: Option<String>,
    /// The block clicked, which must be in a loaded chunk. Default: none, a click at the air.
    pub block: Option<handles::Block>,
    /// Which face of `block` was clicked. Default `"up"`; only with `block`.
    pub face: Option<String>,
}

/// The keys `nf.test.input` holds down: each `true` is held, and one left out (or `false`) isn't. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestInputKeys {
    /// Forward (W).
    pub forward: Option<bool>,
    /// Back (S).
    pub backward: Option<bool>,
    /// Left (A).
    pub left: Option<bool>,
    /// Right (D).
    pub right: Option<bool>,
    /// Jump (space).
    pub jump: Option<bool>,
    /// Sneak (shift).
    pub sneak: Option<bool>,
    /// Sprint (control).
    pub sprint: Option<bool>,
}

/// How `nf.test.accept` answers. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestAcceptOptions {
    /// A stream's status: 100 to 599. Default `200`.
    pub status: Option<i64>,
    /// The response headers (names are lowercased). Default: none.
    pub headers: Option<BTreeMap<String, String>>,
    /// A WebSocket's chosen subprotocol: one of those it offered. Default: none.
    pub protocol: Option<String>,
}

/// How `nf.test.disconnect` ends a connection. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestDisconnectOptions {
    /// A WebSocket's close code. Default `1000`.
    pub code: Option<i64>,
    /// A WebSocket's close reason, its `end` event's `detail`.
    pub reason: Option<String>,
    /// Break it instead: it ends `"failed"`, with this as `detail`.
    pub error: Option<String>,
}

/// What `nf.test.request` sends. Every key is optional; a key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestRequestOptions {
    /// Request headers by name.
    pub headers: Option<BTreeMap<String, String>>,
    /// The body. Default none.
    pub body: Option<String>,
    /// The address it comes from. Default `"127.0.0.1"`.
    pub ip: Option<String>,
}

/// What `nf.test.allow_private` takes: one entry of the owner's `http.allow-private`, in a test. A key that isn't one of these is an error.
#[derive(Clone, Debug)]
pub struct TestPrivateAllowance {
    /// The package's namespace.
    pub package: String,
    /// The address (or `localhost`) it may reach though private. In a test a name isn't looked up.
    pub host: String,
    /// The one port, from 1 to 65535.
    pub port: i64,
    /// Its own rate for these requests, as the owner's `requests-per-minute` on the entry (0 for no limit). Default: they count against the package's rate.
    pub requests_per_minute: Option<i64>,
}

/// What `nf.test.request` gives back: the answer as the client got it.
#[derive(Clone, Debug)]
pub struct TestWebResponse {
    /// The status code.
    pub status: i64,
    /// The response headers by name in lowercase.
    pub headers: BTreeMap<String, String>,
    /// The body (empty for a `HEAD`).
    pub body: String,
}

/// What `nf.test.raise` gives back.
#[derive(Clone, Debug)]
pub struct RaisedEvent {
    /// Whether a handler called `event:cancel()` (always `false` for an event that can't be cancelled).
    pub cancelled: bool,
    /// The payload as the handlers left it: a writable field they assigned (`message`) holds what they set.
    pub event: Value,
}
